const BIO_BANK_PREFIX_ALIASES: Record<string, string> = {
  "bio:k6:baum": "bio:k6:baeume",
  "bio:k6:wald-nahrung": "bio:k6:nahrung",
  "bio:k6:spinnen": "bio:spinnen",
  "bio:k6:wirbellose": "bio:k6:wirbellose",
  "bio:k6:insekten": "bio:k6:insekten"
}

/**
 * Merge extras by conceptPrefix. Existing bank items win (never overwrite wissen).
 * Adds Begriffs-/Faktenvielfalt so ~10 unique tasks/round stay normal.
 */
export function deepenBioBank(bank: BioBank): BioBank {
  const rawPrefix = bank.conceptPrefix?.trim()
  const prefix = rawPrefix
    ? (BIO_BANK_PREFIX_ALIASES[rawPrefix] ?? rawPrefix)
    : undefined
  let extra = prefix ? BIO_BANK_EXTRAS[prefix] : undefined
  if (!extra) {
    const sample =
      bank.pairs?.[0]?.concept ?? bank.facts?.[0]?.concept ?? bank.trueFalse?.[0]?.concept ?? ''
    const keys = Object.keys(BIO_BANK_EXTRAS).sort((a, b) => b.length - a.length)
    const hit = keys.find((k) => sample.startsWith(k + ':') || sample === k)
    if (hit) extra = BIO_BANK_EXTRAS[hit]
  }
  if (!extra) return bank
  const seen = new Set<string>()
  const take = <T extends { concept?: string }>(arr: T[] | undefined): T[] => {
    const outArr: T[] = []
    for (const item of arr ?? []) {
      const c = item.concept?.trim()
      if (c && seen.has(c)) continue
      if (c) seen.add(c)
      outArr.push(item)
    }
    return outArr
  }
  // Existing items first — Fachwissen/wissen on prior entries stay untouched.
  return {
    ...bank,
    facts: take([...(bank.facts ?? []), ...(extra.facts ?? [])]),
    pairs: take([...(bank.pairs ?? []), ...(extra.pairs ?? [])]),
    trueFalse: take([...(bank.trueFalse ?? []), ...(extra.trueFalse ?? [])]),
  }
}
